import React, { useContext } from 'react';
import AppContext from '../../contexts';
import { Avatar, Box, Card, CardContent, CardHeader, CardMedia, Grid2 as Grid, Typography, useTheme } from '@mui/material';
import { W } from 'react-router/dist/development/fog-of-war-CvttGpNz';
import { useNavigate } from 'react-router';

export default function PostsView() {
    const { posts } = useContext(AppContext);

    return <Posts posts={posts} />;
}

function Posts({ posts }: { posts: any[] }) {
    return (
        <Grid container spacing={2}>
            {posts.map((post, index) => (
                <Grid key={post.id} size={{ xs: 6 }}>
                    <Post key={index} post={post} />
                </Grid>
            ))}
        </Grid>
    );

}

function Post({ post }: { post: any }) {
    const navigate = useNavigate();
    return (
        <Grid
            container
            sx={{
                cursor: 'pointer',
                transition: 'all 0.5s',
                ':hover': { transform: 'scale(1.05)' }
            }}
            onClick={() => navigate(`/post/${post.id}`)}
        >
            <Grid
                size={12}
                sx={{
                    textAlign: 'center',
                    aspectRatio: '1 / 1',
                    overflow: 'hidden'
                }}>
                <Box
                    component="img"
                    src={post.image_urls[0]}
                    sx={{ width: '100%' }}
                />
            </Grid>
            <Grid size={12} sx={{ paddingTop: 1 }}>
                <Typography sx={{ color: 'text.secondary' }}>
                    {post.user.user_metadata?.name}
                </Typography>
                <Typography sx={{ fontWeight: 'bold' }}>
                    {post.title}
                </Typography>
            </Grid>
        </Grid>
    );
}