import React, { createContext, useState, useEffect, ReactNode } from 'react';
import { supabase } from '../supabase';
import { User } from '@supabase/supabase-js';

interface UserContextType {
    user: User | null;
    setUser: React.Dispatch<React.SetStateAction<User | null>>;
}

interface ImageContextType {
    images: string[];
    setImages: React.Dispatch<React.SetStateAction<string[]>>;
}

interface PostContextType {
    posts: any[];
    setPosts: React.Dispatch<React.SetStateAction<any[]>>;
}

interface AppContextType extends UserContextType, PostContextType {
    fetchPosts: () => Promise<void>;
}

export const AppContext = createContext<AppContextType>({
    user: null,
    setUser: () => { },
    posts: [],
    setPosts: () => { },
    fetchPosts: async () => { },
});

interface AppProviderProps {
    children: ReactNode;
}

export const AppProvider: React.FC<AppProviderProps> = ({ children }) => {
    const [user, setUser] = useState<User | null>(null);
    const [posts, setPosts] = useState<any[]>([]);

    useEffect(() => {
        const listener = supabase.auth.onAuthStateChange((_event, session) => {
            setUser(session?.user || null);
        });
        return () => {
            listener.data.subscription.unsubscribe();
        }
    }, []);

    const fetchPosts = async () => {
        const { data, error } = await supabase
            .from("posts")
            .select(`
                *,
                users(email, raw_user_meta_data)
            `)
            .order('created_at', { ascending: false });

        if (error) {
            console.error(error);
            return;
        }

        const sanityData = data.map((post) => {
            const { title, description, users, image_urls, ...restPost } = post;
            const { raw_user_meta_data, ...restUsers } = users;
            return {
                title: title || '(empty)',
                description: description || '(empty)',
                ...restPost,
                image_urls: image_urls.length > 0 ? image_urls : ['empty.png'],
                user: {
                    user_metadata: JSON.parse(raw_user_meta_data),
                    ...restUsers,
                }
            };
        });

        setPosts(sanityData);
    }

    useEffect(() => {
        fetchPosts();
    }, []);

    return (
        <AppContext.Provider value={{ user, setUser, posts, setPosts, fetchPosts }}>
            {children}
        </AppContext.Provider>
    );
};

export default AppContext;