import React, { useContext } from 'react';
import { useNavigate, useParams } from 'react-router';
import AppContext from '../../contexts';
import ArrowBackIosNewIcon from '@mui/icons-material/ArrowBackIosNew';
import { Box, Button, Grid2 as Grid, Skeleton, Typography, useTheme } from '@mui/material';
import Carousel from 'react-material-ui-carousel'

export default function PostDetailView() {
    const { id } = useParams();

    return (
        <PostDetailById id={id || ''} />
    );
}
function PostDetailById({ id }: { id: string }) {
    const { posts } = useContext(AppContext);
    const post = posts.find((post) => `${post.id}` === id);

    return (
        <PostDetail post={post} />
    );
}
function PostDetail({ post }: { post: any }) {
    const navigate = useNavigate();
    if (!post) {
        return (
            <Skeleton />
        )
    }

    return (
        <Grid container spacing={2} sx={{ marginTop: 2 }}>
            <Grid size={12}>
                <Button
                    color="inherit"
                    variant="outlined"
                    startIcon={<ArrowBackIosNewIcon />}
                    onClick={() => navigate(`/`)}
                >
                    Go Back
                </Button>
            </Grid>
            <Grid size={12}>
                <Typography variant="body1" sx={{ color: 'text.secondary' }}>
                    {post.user.user_metadata?.name}
                </Typography>
                <Typography variant="h3" fontWeight="bold">
                    {post.title}
                </Typography>
                <Carousel>
                    {post.image_urls.map((image: string, index: number) => (
                        <Grid
                            key={index}
                            size={12}
                            sx={{
                                textAlign: 'center',
                                aspectRatio: '1 / 1',
                                overflow: 'hidden'
                            }}>
                            <Box
                                component="img"
                                src={image}
                                sx={{ width: '100%' }}
                            />
                        </Grid>
                    ))}
                </Carousel>
                <Typography variant="body1" sx={{ marginTop: 2 }}>
                    {post.description}
                </Typography>
            </Grid>
        </Grid>

    )
}