import React, { useRef } from 'react';
import { TextField, Button, Typography, List, ListItem, ListItemText, ListItemAvatar, Avatar, Grid2 as Grid, Paper, CardActionArea, FormControl, Backdrop, CircularProgress, Snackbar } from '@mui/material';
import { Navigate, useNavigate } from 'react-router';
import ArrowBackIosNewIcon from '@mui/icons-material/ArrowBackIosNew';
import FileUploadOutlinedIcon from '@mui/icons-material/FileUploadOutlined';
import { AppContext } from '../../contexts';
import { supabase } from '../../supabase';

export default function CreatePost() {
    const navigate = useNavigate();
    const { fetchPosts, user } = React.useContext(AppContext);
    const [loading, setLoading] = React.useState(false);
    const [files, setFiles] = React.useState<FileList | null>(null);
    const [title, setTitle] = React.useState<string>("");
    const [description, setDescription] = React.useState<string>("");
    const [message, setMessage] = React.useState('');
    const [messageOpen, setMessageOpen] = React.useState(false);

    function setSnack(message: string) {
        setMessage(message);
        setMessageOpen(true);
    }
    if (!user) {
        return <Navigate to="/" replace />;
    }

    async function createPostWithLoading() {
        try {
            setLoading(true);
            await createPost();
        } finally {
            setLoading(false);
        }
    }

    async function createPost() {
        if (!files || !title || !description) {
            setSnack("請填寫所有欄位");
            return;
        }

        const image_urls = [];
        if (files) {
            for (let i = 0; i < files.length; i++) {
                const file = files[i];
                const filePath = `${user?.id}/${Date.now()}${file.name.split(".").pop()}`;
                const { data, error } = await supabase.storage.from("images").upload(filePath, file);

                if (error) {
                    console.error("上傳失敗", error);
                    return;
                }
                const url = supabase.storage.from("images").getPublicUrl(data.path).data.publicUrl;
                image_urls.push(url);
            }
        }

        const { error } = await supabase
            .from('posts')
            .insert([
                {
                    title,
                    description,
                    image_urls,
                }
            ]);

        if (error) {
            setSnack("發佈失敗");
        } else {
            setSnack("發佈成功");
            fetchPosts();
            navigate('/');
            return;
        }
    }

    return (
        <Grid container spacing={2} sx={{ marginTop: 2 }}>
            <Grid size={12}>
                <Button
                    color="inherit"
                    variant="outlined"
                    startIcon={<ArrowBackIosNewIcon />}
                    onClick={() => navigate(`/`)}
                >
                    Go Back
                </Button>
            </Grid>
            <Grid size={12}>
                <ImageArea files={files} setFiles={setFiles} />
            </Grid>
            <Grid size={12}>
                <FormControl fullWidth>
                    <TextField
                        label="Title"
                        variant="standard"
                        value={title}
                        onChange={(event) => setTitle(event.target.value)}
                    />
                </FormControl>
            </Grid>
            <Grid size={12}>
                <FormControl fullWidth>
                    <TextField
                        label="Description"
                        variant="standard"
                        multiline
                        minRows={4}
                        value={description}
                        onChange={(event) => setDescription(event.target.value)}
                    />
                </FormControl>
            </Grid>
            <Grid size={12}>
                <FormControl fullWidth>
                    <Button
                        color="inherit"
                        variant="outlined"
                        onClick={createPostWithLoading}
                    >
                        Upload
                    </Button>
                </FormControl>
            </Grid>
            <Backdrop
                open={loading}
            >
                <CircularProgress color="inherit" />
            </Backdrop>
            <Snackbar
                anchorOrigin={{ vertical: 'top', horizontal: 'center' }}
                message={message}
                open={messageOpen}
                onClose={() => setMessageOpen(false)}
                autoHideDuration={3000}
            />
        </Grid>
    );
}

function ImageArea({ files, setFiles }: { files: FileList | null, setFiles: (files: FileList | null) => void }) {
    return (!files || files.length === 0) ? (
        <UploadImageArea setFiles={setFiles} />
    ) : (
        <DisplayImageArea files={files} />
    )
}

function UploadImageArea({ setFiles }: { setFiles: (files: FileList | null) => void }) {
    const fileInputRef = useRef<HTMLInputElement | null>(null);

    return (
        <CardActionArea onClick={() => fileInputRef.current?.click()}>
            <Paper elevation={1} sx={{ padding: 2, borderRadius: 2, height: 300, display: 'flex', justifyContent: 'center', alignItems: 'center' }}>
                <Grid container sx={{ textAlign: 'center' }}>
                    <Grid size={12}>
                        <Typography fontWeight="bold" sx={{ marginBottom: 2 }}>
                            請上傳你的圖片
                        </Typography>
                    </Grid>
                    <Grid size={12}>
                        <FileUploadOutlinedIcon fontSize="large" />
                    </Grid>
                </Grid>
            </Paper>
            <input type="file" multiple hidden ref={fileInputRef} onChange={(event) => { setFiles(event.target.files) }} />
        </CardActionArea>
    );
}

function DisplayImageArea({ files }: { files: FileList }) {
    return (
        <Paper elevation={1} sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
            <List>
                {Array.from(files).map((file, index) => (
                    <ListItem key={index}>
                        <ListItemAvatar>
                            <Avatar src={URL.createObjectURL(file)} variant="square" />
                        </ListItemAvatar>
                        <ListItemText primary={files[index].name} />
                    </ListItem>
                ))}
            </List>
        </Paper>
    );
}
