import React from 'react';
import { AppBar, Container, Toolbar, Typography, Tooltip, IconButton, Avatar, Menu, MenuItem, Box } from "@mui/material";
import { supabase } from '../../supabase';
import { useAnchorEl } from '../../hook';
import { AppContext } from '../../contexts';
import AddBoxOutlinedIcon from '@mui/icons-material/AddBoxOutlined';
import { useNavigate } from 'react-router';


function TopBar() {
    return (
        <>
            <AppBar color="inherit" elevation={1}>
                <Container maxWidth="sm">
                    <Toolbar>
                        <Typography variant="h6" component="div" fontFamily="serif">
                            Purr Purr Kitty
                        </Typography>
                        <Box sx={{ flexGrow: 1 }} />
                        <Box sx={{ alignItems: 'flex-end' }}>
                            <CreatePostButton />
                            <UserMenuIcon />
                        </Box>
                    </Toolbar>
                </Container>
            </AppBar>
            <Toolbar /> {/* Spacer to push content below the AppBar */}
        </>
    );
}

function CreatePostButton() {
    const { user } = React.useContext(AppContext);
    const navigate = useNavigate();

    if (!user) return <></>;

    return (
        <IconButton
            sx={{ marginRight: 2 }}
            onClick={() => navigate('/create-post')}
        >
            <AddBoxOutlinedIcon />
        </IconButton>
    )

}

function UserMenuIcon() {
    const { user } = React.useContext(AppContext);
    const [anchorElUser, handleOpenUserMenu, handleCloseUserMenu] = useAnchorEl();

    const handleLoginIn = () => {
        supabase.auth.signInWithOAuth({
            provider: "google",
            options: {
                redirectTo: window.location.origin,
            }
        });
    }
    const handleLoginLogout = () => {
        supabase.auth.signOut();
        handleCloseUserMenu();
    };

    return (
        <>
            <IconButton onClick={handleOpenUserMenu} sx={{ p: 0 }}>
                <Avatar src={user?.user_metadata?.avatar_url} />
            </IconButton>
            <Menu
                anchorEl={anchorElUser}
                open={!!anchorElUser}
                onClose={handleCloseUserMenu}
            >
                {!user
                    ? <MenuItem onClick={handleLoginIn}>Login</MenuItem>
                    : <MenuItem onClick={handleLoginLogout}>Logout</MenuItem>
                }
                {/* <MenuItem>Switch Language</MenuItem> */}
            </Menu>
        </>
    )
}


export default TopBar;